// MAVLink: framing against pymavlink-generated bytes, and the adapter
// against a pymavlink vehicle over real UDP (skipped without pymavlink).
@TestOn('vm')
library;

import 'dart:convert';
import 'dart:io';
import 'dart:math' as math;

import 'package:flutter_test/flutter_test.dart';
import 'package:koebelt_dash/core/dash.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:koebelt_dash/core/model.dart';
import 'package:koebelt_dash/core/sequence.dart';
import 'package:koebelt_dash/core/telemetry.dart';
import 'package:koebelt_dash/link/bytes.dart';
import 'package:koebelt_dash/link/mavlink.dart';
import 'package:koebelt_dash/link/mavlink_adapter.dart';
import 'package:koebelt_dash/link/protocol.dart';
import 'package:koebelt_dash/link/session.dart';

List<int> unhex(String s) => [for (var i = 0; i < s.length; i += 2) int.parse(s.substring(i, i + 2), radix: 16)];
String hex(List<int> b) => b.map((x) => x.toRadixString(16).padLeft(2, '0')).join();

Future<void> wait(int ms) => Future<void>.delayed(Duration(milliseconds: ms));

void main() {
  // Frames made by pymavlink (sys 1, comp 1, seq 7 and 8).
  const hb = 'fd0900000701010000000500000002035104031f30';
  const att = 'fd1c00000801011e0000d2040000cdcccc3dcdcc4cbe0000c03f0ad7233c0ad7a33c8fc2f53ce43a';

  test('encodes byte for byte like pymavlink', () {
    final e = MavEncoder(sys: 1, comp: 1);
    for (var i = 0; i < 7; i++) {
      e.encode(Mav.heartbeat, {});
    }
    expect(hex(e.encode(Mav.heartbeat, {'custom_mode': 5, 'type': 2, 'autopilot': 3, 'base_mode': 81, 'system_status': 4, 'mavlink_version': 3})), hb);
    expect(
      hex(e.encode(Mav.attitude, {'time_boot_ms': 1234, 'roll': .1, 'pitch': -.2, 'yaw': 1.5, 'rollspeed': .01, 'pitchspeed': .02, 'yawspeed': .03})),
      att,
    );
  });

  test('PX4 and ArduPilot IMU messages decode like pymavlink made them', () {
    // SCALED_IMU (mg, mrad/s) and HIGHRES_IMU (SI) from pymavlink.
    const scaled = 'fd1700000901011a0000d20400000a00ecffd403010002000300040005000600fadc6b';
    const highres =
        'fd3d00000a01016900002e16000000000000cdcccc3dcdcc4cbecdcc1c410ad7233c0ad7a33c8fc2f53ccdcc4c3e9a99993ecdcccc3e00407d44000000000000c8430000c84107f576';
    final ms = MavParser().add(unhex(scaled + highres));
    expect(ms.map((m) => m.id), [Mav.scaledImu, Mav.highresImu]);
    expect(ms[0].n('zacc'), 980);
    expect(ms[0].n('temperature'), 250);
    expect(ms[1].n('zacc'), closeTo(9.8, 1e-5));
    expect(ms[1].n('zgyro'), closeTo(.03, 1e-6));
    // Through the adapter: both become the app's imu channel.
    final t = MavlinkTransport(MemoryByteLink.pair().$1);
    final got = <Map>[];
    t.tap = (m) => m['t'] == 'tlm' ? got.add(m['d'] as Map) : null;
    for (final m in MavParser().add(unhex(hb))) {
      t.feed(m);
    }
    for (final m in ms) {
      t.feed(m);
    }
    final imu = [for (final d in got) (d['imu'] as List).cast<num>()];
    expect(imu[0][2], closeTo(980 * 9.80665 / 1000, 1e-6));
    expect(imu[1], [
      for (final v in [.1, -.2, 9.8, .01, .02, .03]) closeTo(v, 1e-5),
    ]);
  });

  test('parses split, noisy and truncated frames', () {
    final p = MavParser();
    final bytes = [0x00, 0xFD, 0x13, ...unhex(hb), ...unhex(att)];
    final got = <MavMsg>[];
    for (final b in bytes) {
      got.addAll(p.add([b]));
    }
    expect(got.map((m) => m.name), ['HEARTBEAT', 'ATTITUDE']);
    expect(got[0].n('custom_mode'), 5);
    expect(got[0].n('base_mode'), 81);
    expect(got[1].n('pitch'), closeTo(-.2, 1e-6));
    // Corrupt CRC: dropped.
    final bad = unhex(hb)..[12] ^= 0xFF;
    expect(MavParser().add(bad), isEmpty);
  });

  test('modes map both ways', () {
    expect(mavModeName(Mav.ardupilot, 2, 5), 'LOITER');
    expect(appMode('LOITER'), 'HOLD');
    expect(appMode('ALT_HOLD'), 'MANUAL');
    expect(appMode('AUTO.RTL'), 'RTH');
    expect(mavModeFor('HOLD', Mav.ardupilot, 2), (5.0, 0.0));
    expect(mavModeFor('RTH', Mav.ardupilot, 10), (11.0, 0.0), reason: 'Rover RTL');
    expect(mavModeFor('LAND', Mav.px4, 2), (4.0, 6.0));
    expect(mavModeName(Mav.px4, 2, (4 << 16) | (3 << 24)), 'AUTO.LOITER');
    expect(mavKind(2), 'drone');
    expect(mavKind(10), 'rover');
    expect(mavVehicleName(Mav.ardupilot, 10), 'ArduRover');
  });

  final py = File('../../libs/python/.venv/bin/python');
  final hasPymavlink = py.existsSync() && Process.runSync(py.path, ['-c', 'import pymavlink']).exitCode == 0;

  test(
    'flies a pymavlink ArduCopter: telemetry, params, modes, sticks, goto, STOP',
    () async {
      const vport = 14571, gport = 14581;
      final proc = await Process.start(py.path, ['test/fixtures/mav_vehicle.py', '$vport', '$gport', '6']);
      final out = proc.stdout.transform(utf8.decoder).join();
      final err = proc.stderr.transform(utf8.decoder).join();
      addTearDown(proc.kill);

      final got = <Msg>[];
      final tel = Telemetry(DeviceKind.drone);
      final tr = MavlinkTransport(HubByteLink(host: '127.0.0.1', port: vport, localPort: gport));
      final s = DeviceSession(
        tr,
        onMessage: (m) {
          got.add(m);
          if (m['t'] == 'tlm') tel.applyTlm((m['d'] as Map).cast<String, dynamic>());
          if (m['t'] == 'state') tel.applyState(m);
        },
      );
      var ctl = [0.0, 0.0, 0.0, 0.0];
      s.axes = () => ctl;
      final hello = await s.open();
      expect(hello['kind'], 'drone');
      expect(hello['name'], 'ArduCopter');
      await wait(1500);

      expect(tel.hasGps, isTrue);
      expect(tel.lat, closeTo(47.3769, 1e-4));
      expect(tel.battery, closeTo(76, .1));
      expect(tel.pos[2], closeTo(0, .1), reason: 'relative altitude from GLOBAL_POSITION_INT');
      expect(got.any((m) => m['t'] == 'log' && '${m['msg']}'.contains('PreArm')), isTrue);
      final params = parseParams(got.lastWhere((m) => m['t'] == 'params'), DeviceKind.drone);
      expect(params.expand((g) => g.params).map((p) => p.key), containsAll(['ATC_RAT_RLL_P', 'WPNAV_SPEED', 'FS_GCS_ENABLE']));
      expect(s.latency, greaterThan(0), reason: 'TIMESYNC round trip');

      s.send({
        't': 'pset',
        'p': {'ATC_RAT_RLL_P': 0.2},
      });
      s.send({'t': 'arm', 'v': true});
      await wait(800);
      expect(got.any((m) => m['t'] == 'pack' && (m['keys'] as List).contains('ATC_RAT_RLL_P')), isTrue);
      expect(tel.armed, isTrue);

      s.send({'t': 'mode', 'm': 'HOLD'});
      await wait(800);
      expect(tel.mode, 'HOLD');
      expect(got.lastWhere((m) => m['t'] == 'state')['ext']['fc_mode'], 'LOITER');

      s.send({'t': 'mode', 'm': 'MANUAL'});
      await wait(700);
      ctl = [0.0, 1.0, 0.0, 0.5]; // full throttle up, half forward
      await wait(500);
      s.send({
        't': 'cmd',
        'c': 'goto',
        'a': {'x': 20, 'y': 10, 'z': 15},
      });
      await wait(800);
      expect(tel.pos[0], closeTo(20, .5));
      expect(tel.pos[1], closeTo(10, .5));
      s.send({'t': 'stop'});
      await wait(1100); // the vehicle reports arming in its 2 Hz heartbeat
      expect(tel.armed, isFalse);
      expect(tel.estop, isTrue);

      await s.close();
      final summary = jsonDecode((await out).trim().split('\n').last) as Map;
      expect(summary['gcs_heartbeats'], greaterThan(2));
      expect(summary['param_sets']['ATC_RAT_RLL_P'], closeTo(.2, 1e-6));
      expect(summary['modes'], containsAll([5, 2]), reason: 'LOITER, then ALT_HOLD for manual');
      expect(summary['manual'], greaterThan(3));
      expect(summary['last_manual'], [500, 0, 1000, 0], reason: 'x forward, z throttle 0..1000 with 500 = hold');
      expect(summary['reposition'][3], 6);
      expect(summary['force_disarm'], isTrue);
      expect(summary['intervals'], greaterThan(0));
      expect(await err, isEmpty);
    },
    skip: hasPymavlink ? false : 'needs pymavlink in libs/python/.venv',
    timeout: const Timeout(Duration(seconds: 40)),
  );

  test(
    'through the app: add by address, connect, arm, hold, STOP',
    () async {
      // The app listens on 14550 like any ground station.
      const vport = 14572;
      final proc = await Process.start(py.path, ['test/fixtures/mav_vehicle.py', '$vport', '14550', '6']);
      addTearDown(proc.kill);
      TestWidgetsFlutterBinding.ensureInitialized();
      SharedPreferences.setMockInitialValues({});
      final d = Dash();
      await d.init();
      final dev = d.addManual('Copter', '127.0.0.1:$vport', DeviceKind.drone, proto: 'mavlink');
      await d.connect(dev.id);
      expect(d.connectError, isNull);
      expect(d.device?.name, 'ArduCopter');
      expect(d.canControl, isTrue);
      await wait(1200);
      expect(d.liveTel.hasGps, isTrue);
      d.setArmed(true);
      await wait(700);
      expect(d.liveTel.armed, isTrue);
      d.setMode('HOLD');
      await wait(700);
      expect(d.liveTel.mode, 'HOLD');
      d.emergencyStop();
      await wait(700);
      expect(d.liveTel.armed, isFalse);
      await d.disconnect();
      d.dispose();
    },
    skip: hasPymavlink ? false : 'needs pymavlink in libs/python/.venv',
    timeout: const Timeout(Duration(seconds: 40)),
  );

  test(
    'through the app: a sequence becomes a mission the vehicle flies',
    () async {
      const vport = 14573;
      final proc = await Process.start(py.path, ['test/fixtures/mav_vehicle.py', '$vport', '14550', '10']);
      addTearDown(proc.kill);
      final out = proc.stdout.transform(utf8.decoder).join();
      TestWidgetsFlutterBinding.ensureInitialized();
      SharedPreferences.setMockInitialValues({});
      final d = Dash();
      await d.init();
      final dev = d.addManual('Copter', '127.0.0.1:$vport', DeviceKind.drone, proto: 'mavlink');
      await d.connect(dev.id);
      expect(d.seqCap, greaterThan(0), reason: 'ArduPilot takes missions');
      await wait(1200); // home from the first position fix

      Future<void> until(bool Function() ok, int ms) async {
        final sw = Stopwatch()..start();
        while (!ok() && sw.elapsedMilliseconds < ms) {
          await wait(20);
          d.tick(.02);
        }
      }

      // A step a mission cannot hold: the app runs it instead.
      d.runSequence(
        Sequence(
          id: 'spd',
          name: 'Speed',
          kind: DeviceKind.drone,
          steps: [
            SeqStep('speed', {'pct': 50.0}),
            SeqStep('wait', {'s': .1}),
          ],
        ),
      );
      await until(() => d.runner?.onDevice == false, 3000);
      expect(d.runner?.message, contains('Speed limit'));
      d.runner!.stop('x');

      final q = Sequence(
        id: 'm1',
        name: 'Mission',
        kind: DeviceKind.drone,
        steps: [
          SeqStep('arm', {'v': 'ARM'}),
          SeqStep('takeoff', {'alt': 10.0}),
          SeqStep('goto', {'x': 20.0, 'y': 10.0, 'z': 15.0}),
          SeqStep('wait', {'s': 1.0}),
          SeqStep('land', {}),
        ],
      );
      d.runSequence(q);
      final r = d.runner!;
      expect(r.onDevice, isTrue);
      await until(() => r.state == RunState.done || r.state == RunState.failed, 8000);
      expect(r.state, RunState.done, reason: r.message);
      await d.disconnect();
      d.dispose();

      final summary = jsonDecode((await out).trim().split('\n').last) as Map;
      final items = summary['mission'] as List;
      // Home, take off, waypoint, loiter, land.
      expect([for (final i in items) i[0]], [16, 22, 16, 19, 21]);
      expect(items[1][3], 10.0);
      expect(items[2][1], closeTo(47.3769 + 10 / 111111, 2e-7));
      expect(items[2][2], closeTo(8.5417 + 20 / (111111 * math.cos(47.3769 * math.pi / 180)), 2e-7));
      expect(items[2][3], 15.0);
      expect(items[3][4], 1.0, reason: 'loiter time');
      expect(items[2][5], Mav.frameGlobalRelativeAltInt);
      expect(summary['arm'], contains(true));
      expect(summary['reached'], [1, 2, 3, 4]);
    },
    skip: hasPymavlink ? false : 'needs pymavlink in libs/python/.venv',
    timeout: const Timeout(Duration(seconds: 40)),
  );

  test(
    'through the app: a mission the vehicle refuses to start fails with its reason',
    () async {
      const vport = 14574;
      final proc = await Process.start(py.path, ['test/fixtures/mav_vehicle.py', '$vport', '14550', '6', 'refuse-auto']);
      addTearDown(proc.kill);
      TestWidgetsFlutterBinding.ensureInitialized();
      SharedPreferences.setMockInitialValues({});
      final d = Dash();
      await d.init();
      final dev = d.addManual('Copter', '127.0.0.1:$vport', DeviceKind.drone, proto: 'mavlink');
      await d.connect(dev.id);
      await wait(1200);
      d.runSequence(
        Sequence(
          id: 'm2',
          name: 'Refused',
          kind: DeviceKind.drone,
          steps: [
            SeqStep('arm', {'v': 'ARM'}),
            SeqStep('takeoff', {'alt': 10.0}),
            SeqStep('land', {}),
          ],
        ),
      );
      final r = d.runner!;
      final sw = Stopwatch()..start();
      while (r.state == RunState.running && sw.elapsedMilliseconds < 5000) {
        await wait(20);
        d.tick(.02);
      }
      expect(r.state, RunState.failed, reason: 'not stuck at "Starting the mission"');
      expect(r.message, contains('requires position'));
      await d.disconnect();
      d.dispose();
    },
    skip: hasPymavlink ? false : 'needs pymavlink in libs/python/.venv',
    timeout: const Timeout(Duration(seconds: 30)),
  );
}
